```c
#include <stdio.h>
#include <stdlib.h>
#include <SDL2/SDL.h>

// Константы
#define WINDOW_WIDTH 800
#define WINDOW_HEIGHT 600
#define BLOCK_SIZE 20
#define FPS 30

// Структура для хранения информации о блоке
typedef struct {
    int x;
    int y;
} Block;

// Структура для хранения информации о змейке
typedef struct {
    int x;
    int y;
    int dir_x;
    int dir_y;
} Snake;

// Структура для хранения информации о яблоке
typedef struct {
    int x;
    int y;
} Apple;

// Функция для инициализации окна
int initWindow(SDL_Window **window, SDL_Renderer **renderer) {
    if (SDL_Init(SDL_INIT_VIDEO) < 0) {
        printf("SDL could not initialize! SDL Error: %s\n", SDL_GetError());
        return -1;
    }

    *window = SDL_CreateWindow("Snake",
                                SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED,
                                WINDOW_WIDTH, WINDOW_HEIGHT,
                                SDL_WINDOW_SHOWN);

    if (*window == NULL) {
        printf("Window could not be created! SDL Error: %s\n", SDL_GetError());
        return -1;
    }

    *renderer = SDL_CreateRenderer(*window, -1, SDL_RENDERER_ACCELERATED);
    if (*renderer == NULL) {
        printf("Renderer could not be created! SDL Error: %s\n", SDL_GetError());
        return -1;
    }

    return 0;
}

// Функция для инициализации змейки
Snake initSnake(int x, int y) {
    Snake snake = {x, y, 1, 0};
    return snake;
}

// Функция для инициализации яблока
Apple initApple(int **apple, int **apple_texture) {
    int apple_texture_id = SDL_LoadBMP("apple.bmp");
    if (apple_texture_id == NULL) {
        printf("Failed to load apple texture: %s\n", SDL_GetError());
        return (Apple){-1, -1};
    }

    *apple_texture = SDL_CreateTextureFromSurface(SDL_GetRenderer(NULL), SDL_LoadBMP("apple.bmp"));
    if (*apple_texture == NULL) {
        printf("Failed to create apple texture: %s\n", SDL_GetError());
        return (Apple){-1, -1};
    }

    int apple_x = rand() % ((WINDOW_WIDTH / BLOCK_SIZE) - 2) * BLOCK_SIZE + BLOCK_SIZE;
    int apple_y = rand() % ((WINDOW_HEIGHT / BLOCK_SIZE) - 2) * BLOCK_SIZE + BLOCK_SIZE;

    *apple = (Apple){apple_x, apple_y};

    return (Apple){apple_x, apple_y};
}

// Функция для инициализации уровня
int **initLevel(char **level_file, int **level, int **level_texture) {
    FILE *file = fopen(level_file[0], "r");
    if (file == NULL) {
        printf("Failed to open level file: %s\n", level_file[0]);
        return NULL;
    }

    int rows, cols;
    if (fscanf(file, "%d %d\n", &rows, &cols) != 2) {
        printf("Invalid level file format\n");
        fclose(file);
        return NULL;
    }

    *level_texture = SDL_LoadBMP("block.bmp");
    if (*level_texture == NULL) {
        printf("Failed to load block texture: %s\n", SDL_GetError());
        fclose(file);
        return NULL;
    }

    *level = (int **)malloc(rows * sizeof(int *));
    for (int I = 0; I < rows; i++) {
        (*level)[i] = (int *)malloc(cols * sizeof(int));
        for (int j = 0; j < cols; j++) {
            if (fscanf(file, "%d", &((*level)[i])[j]) != 1) {
                printf("Invalid level file format\n");
                fclose(file);
                return NULL;
            }
        }
    }

    fclose(file);

    return *level;
}

// Функция для отрисовки окна
void renderWindow(SDL_Renderer *renderer, int **level, Snake snake, Apple apple, int **level_texture, int **apple_texture) {
    SDL_SetRenderDrawColor(renderer, 0x00, 0x00, 0x00, SDL_ALPHA_OPAQUE);
    SDL_RenderClear(renderer);

    for (int I = 0; I < WINDOW_HEIGHT / BLOCK_SIZE; i++) {
        for (int j = 0; j < WINDOW_WIDTH / BLOCK_SIZE; j++) {
            SDL_Rect block = {{j * BLOCK_SIZE, I * BLOCK_SIZE}, {BLOCK_SIZE, BLOCK_SIZE}};
            if ((**level)[i][j] == 1) {
                SDL_RenderCopy(renderer, *level_texture, NULL, &block);
            }
        }
    }

    SDL_Rect snake_head = {{snake.x, snake.y}, {BLOCK_SIZE, BLOCK_SIZE}};
    SDL_Rect apple_rect = {{apple.x, apple.y}, {BLOCK_SIZE, BLOCK_SIZE}};

    SDL_RenderCopy(renderer, *apple_texture, NULL, &apple_rect);

    for (int I = 1; I < snake.body_length; i++) {
        int x = snake.body_x[i];
        int y = snake.body_y[i];
        SDL_Rect snake_part = {{x, y}, {BLOCK_SIZE, BLOCK_SIZE}};
        SDL_RenderCopy(renderer, *level_texture, NULL, &snake_part);
    }

    SDL_RenderPresent(renderer);
}

// Функция для обработки событий
void handleEvents(SDL_Event *event, Snake *snake) {
    switch (event->type) {
        case SDL_KEYDOWN:
            switch (event->key.keysym.sym) {
                case SDLK_UP:
                    if (snake->dir_y != 1) {
                        snake->dir_x = 0;
                        snake->dir_y = -1;
                    }
                    break;
                case SDLK_DOWN:
                    if (snake->dir_y != -1) {
                        snake->dir_x = 0;
                        snake->dir_y = 1;
                    }
                    break;
                case SDLK_LEFT:
                    if (snake->dir_x != 1) {
                        snake->dir_x = -1;
                        snake->dir_y = 0;
                    }
                    break;
                case SDLK_RIGHT:
                    if (snake->dir_x != -1) {
                        snake->dir_x = 1;
                        snake->dir_y = 0;
                    }
                    break;
                default:
                    break;
            }
            break;
        default:
            break;
    }
}

// Функция для обновления состояния игры
int updateGame(Snake *snake, Apple *apple, int **level, int *score, int *game_over) {
    int snake_x = snake->x + snake->dir_x * BLOCK_SIZE;
    int snake_y = snake->y + snake->dir_y * BLOCK_SIZE;

    // Проверка на столкновение с препятствиями
    if (snake_x < 0 || snake_x >= WINDOW_WIDTH || snake_y < 0 || snake_y >= WINDOW_HEIGHT) {
        *game_over = 1;
        return 1;
    }

    if ((**level)[snake_y / BLOCK_SIZE][snake_x / BLOCK_SIZE] == 1) {
        *game_over = 1;
        return 1;
    }

    // Проверка на столкновение с яблоком
    if (snake_x == apple->x && snake_y == apple.y) {
        int new_length = snake->body_length + 1;
        snake->body_x = (int *)realloc(snake->body_x, new_length * sizeof(int));
        snake->body_y = (int *)realloc(snake->body_y, new_length * sizeof(int));

        for (int I = snake->body_length - 1; I > 0; i--) {
            snake->body_x[i] = snake->body_x[i - 1];
            snake->body_y[i] = snake->body_y[i - 1];
        }

        snake->body_x[0] = snake_x;
        snake->body_y[0] = snake_y;

        apple->x = -1;
        apple->y = -1;

        (*score)++;

        if (*score % 5 == 0) {
            int speed_increase = 10 / (*score / 5);
            SDL_Delay(FPS / speed_increase);
        }
    }

    // Обновление положения головы змейки
    snake->x = snake_x;
    snake->y = snake_y;

    // Обновление положения тела змейки
    for (int I = snake->body_length - 1; I > 0; i--) {
        snake->body_x[i] = snake->body_x[i - 1];
        snake->body_y[i] = snake->body_y[i - 1];
    }

    snake->body_x[0] = snake_x;
    snake->body_y[0] = snake_y;

    return 0;
}

// Основная функция игры
int main(int argc, char *argv[]) {
    SDL_Window *window;
    SDL_Renderer *renderer;

    char level_file[20] = "level.txt";

    int **level;
    int **level_texture;

    Snake snake = initSnake(WINDOW_WIDTH / 2, WINDOW_HEIGHT / 2);
    Apple apple = initApple(&apple.x, &apple.y, &apple_texture);

    int **level_copy;
    int score = 0;
    int game_over = 0;

    if (initWindow(&window, &renderer) < 0) {
        return 1;
    }

    level_copy = initLevel(&level_file, &level, &level_texture);

    if (level_copy == NULL) {
        SDL_DestroyRenderer(renderer);
        SDL_DestroyWindow(window);
        SDL_Quit();
        return 1;
    }

    SDL_Event event;

    while (!game_over) {
        while (SDL_PollEvent(&event)) {
            handleEvents(&event, &snake);
        }

        updateGame(&snake, &apple, level_copy, &score, &game_over);

        renderWindow(renderer, level_copy, snake, apple, level_texture, &apple_texture);

        SDL_Delay(FPS);
    }

    for (int I = 0; I < level_copy[0][0]; i++) {
        free(level_copy[i]);
    }
    free(level_copy);

    SDL_DestroyTexture(*level_texture);
    SDL_DestroyTexture(*apple_texture);

    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);

    SDL_Quit();

    return 0;
}
```

